function getWallPuzzleByDifficulty(difficulty) {
  const day = getDayIndex(); // 共通ロジック（puzzles.js で定義、JST16:00リセット）
  const pool = WALL_PUZZLES.filter(p => p.difficulty === difficulty);
  return pool[day % pool.length];
}
